const pwaServiceWorker="const CACHE='tgg-creator-os-pwa-v5';const APP='https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?app=1';const OFFLINE='<!doctype html><html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#050505\"><title>Creator OS · Offline</title><style>body{margin:0;background:#050505;color:#fff;font-family:system-ui;display:grid;place-items:center;min-height:100vh}.c{max-width:460px;padding:28px}.m{width:56px;height:56px;border-radius:16px;background:#e50914;display:grid;place-items:center;font-weight:900}.muted{color:#8a8a92;line-height:1.6}</style></head><body><main class=\"c\"><div class=\"m\">TGG</div><h1>Creator OS is offline</h1><p class=\"muted\">Your installed shell is available, but live creator data needs a connection. Reconnect and reopen Creator OS.</p></main></body></html>';self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.add(APP)).catch(()=>{}));self.skipWaiting()});self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('tgg-creator-os-pwa-')&&k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim()});self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET')return;if(e.request.mode==='navigate'||u.href===APP){e.respondWith(fetch(e.request).then(r=>{const copy=r.clone();caches.open(CACHE).then(c=>c.put(APP,copy)).catch(()=>{});return r}).catch(async()=>await caches.match(APP)||new Response(OFFLINE,{headers:{'Content-Type':'text/html; charset=utf-8'}})));}});self.addEventListener('push',e=>{let data={};try{data=e.data?e.data.json():{}}catch{data={body:e.data?e.data.text():''}}const title=String(data.title||'TRU GO GETTA Creator OS');const options={body:String(data.body||'You have a new Creator OS update.'),icon:'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?pwa=icon192',badge:'https://xsofowzvwetamhyuvlpj.supabase.co/functions/v1/tgg-creator-os-app-v17?pwa=icon192',tag:String(data.tag||'tgg-creator-alert'),data:{url:String(data.url||APP)},renotify:false};e.waitUntil(self.registration.showNotification(title,options))});self.addEventListener('notificationclick',e=>{e.notification.close();const target=e.notification?.data?.url||APP;e.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(list=>{for(const c of list){if('focus'in c){c.navigate(target).catch(()=>{});return c.focus()}}return clients.openWindow?clients.openWindow(target):undefined}))});";
function webPushServiceClient(){
 const url=Deno.env.get("SUPABASE_URL");
 let key=Deno.env.get("SUPABASE_SECRET_KEY")||Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")||null;
 if(!key){
   const keys=Deno.env.get("SUPABASE_SECRET_KEYS");
   try{if(keys)key=JSON.parse(keys)?.default??null}catch{}
 }
 if(!url||!key)return null;
 return createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
}
async function ensureWebPushConfig(){
 const svc=webPushServiceClient();if(!svc)return null;
 const {data:existing}=await svc.rpc("tgg_get_provider_secret_service",{p_provider_key:"webpush.vapid"});
 if(existing){try{return JSON.parse(existing)}catch{}}
 const keys=webpush.generateVAPIDKeys();
 const cfg={publicKey:keys.publicKey,privateKey:keys.privateKey,subject:"https://trugogettamixtapes.blogspot.com/"};
 const hook=(crypto.randomUUID()+crypto.randomUUID()).replaceAll("-","");
 const {error}=await svc.rpc("tgg_webpush_bootstrap_service",{p_vapid_json:JSON.stringify(cfg),p_hook_secret:hook});
 if(error){console.error("webpush_bootstrap_failed",error);return null}
 return cfg;
}
