type TggSignupApprovalResult=
 | {ok:true;token:string}
 | {ok:false;error:string;message:string;status:number};

function tggPasswordSafetyMessage(code:string){
 const messages:Record<string,string>={
  minimum_length:"Use at least 8 characters.",
  maximum_length:"Password is too long.",
  weak_password:"Use a stronger password with more variety.",
  known_compromised_password:"That password is known to be compromised. Choose a different one.",
  invalid_signup_context:"Account security context is invalid. Refresh and try again."
 };
 return messages[code]||"Password safety check is unavailable. Try again later.";
}

async function tggSignupApproval(password:string,email:string,signupSource:"creator_os_direct"|"call_validation_invite"):Promise<TggSignupApprovalResult>{
 try{
  const url=Deno.env.get("SUPABASE_URL")||"";
  if(!url)return {ok:false,error:"password_safety_check_unavailable",message:"Password safety check is unavailable. Try again later.",status:503};
  const response=await fetch(url+"/functions/v1/tgg-password-breach-check-v4",{
   method:"POST",
   headers:{"content-type":"application/json"},
   body:JSON.stringify({password,email,signup_source:signupSource})
  });
  const verdict=await response.json().catch(()=>({}));
  if(!response.ok||verdict?.acceptable!==true){
   const code=String(verdict?.reason||verdict?.error||"password_safety_check_unavailable");
   const userError=new Set(["minimum_length","maximum_length","weak_password","known_compromised_password","invalid_signup_context"]).has(code);
   return {ok:false,error:code,message:tggPasswordSafetyMessage(code),status:userError?400:503};
  }
  const token=String(verdict?.approval_token||"");
  if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(token)){
   return {ok:false,error:"signup_approval_missing",message:"Password safety check is unavailable. Try again later.",status:503};
  }
  return {ok:true,token};
 }catch{
  return {ok:false,error:"password_safety_check_unavailable",message:"Password safety check is unavailable. Try again later.",status:503};
 }
}

